(function(){
  'use strict';
  var search=document.getElementById('lesson-search');
  var chapters=Array.prototype.slice.call(document.querySelectorAll('.lesson-chapter'));
  var links=Array.prototype.slice.call(document.querySelectorAll('#table-of-contents a'));
  var sidebar=document.getElementById('sidebar');
  var menu=document.getElementById('menu-toggle');
  var progress=document.getElementById('progress-bar');
  var backTop=document.getElementById('back-top');
  var empty=document.getElementById('empty-state');
  search.addEventListener('input',function(){
    var query=search.value.trim().toLocaleLowerCase();
    var visible=0;
    chapters.forEach(function(chapter){
      var matches=!query||chapter.textContent.toLocaleLowerCase().indexOf(query)!==-1;
      chapter.hidden=!matches;
      if(matches) visible++;
    });
    links.forEach(function(link){
      var target=document.getElementById(link.getAttribute('href').slice(1));
      var chapter=target&&target.closest('.lesson-chapter');
      link.hidden=!!(chapter&&chapter.hidden);
    });
    empty.style.display=visible?'none':'block';
  });
  document.getElementById('print-button').addEventListener('click',function(){window.print();});
  if(menu){menu.addEventListener('click',function(){var open=sidebar.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});}
  links.forEach(function(link){link.addEventListener('click',function(){if(sidebar.classList.contains('open')){sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false');}});});
  document.querySelectorAll('.lesson-chapter pre').forEach(function(pre){
    var button=document.createElement('button');button.type='button';button.className='copy-code';button.textContent='Copy code';
    button.addEventListener('click',function(){
      var code=pre.querySelector('code');var text=code?code.textContent:pre.textContent;
      if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(function(){button.textContent='Copied';setTimeout(function(){button.textContent='Copy code';},1400);}).catch(function(){button.textContent='Copy unavailable';});}
      else{var area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();var copied=document.execCommand('copy');area.remove();button.textContent=copied?'Copied':'Copy unavailable';setTimeout(function(){button.textContent='Copy code';},1400);}
    });pre.appendChild(button);
  });
  function updateScroll(){
    var max=document.documentElement.scrollHeight-window.innerHeight;
    progress.style.width=(max>0?Math.min(100,Math.max(0,window.scrollY/max*100)):0)+'%';
    backTop.style.display=window.scrollY>500?'block':'none';
  }
  window.addEventListener('scroll',updateScroll,{passive:true});updateScroll();
  backTop.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});
  document.addEventListener('keydown',function(event){
    if(event.key==='/'&&!/input|textarea/i.test(document.activeElement.tagName)){event.preventDefault();search.focus();}
    if(event.key==='Escape'&&search.value){search.value='';search.dispatchEvent(new Event('input'));}
  });
}());
</script>
</body>
</html>
